// element structs keep their ordered fast path; the root loop itself is
// the plain array/object protocol.
func zjDecode_Exts(l *zerojson.Lexer, v *Exts, a *zjArenaExts) {
	if *v != nil {
		type container Exts
		if raw := l.RawValue(); l.Err() == nil {
			if err := json_.Unmarshal(raw, (*container)(v)); err != nil {
				l.AddError(err)
			}
		}
		return
	}
	if l.IsNull() {
		*v = nil
		return
	}
	a.cRoot = *v
	a.cRoot = a.cRoot[:0]
	if l.EnterArray() {
		for {
			if len(a.cRoot) == cap(a.cRoot) {
				a.cRoot = append(a.cRoot, Ext{})
			} else {
				a.cRoot = a.cRoot[:len(a.cRoot)+1]
				a.cRoot[len(a.cRoot)-1] = Ext{}
			}
			if !l.IsNull() {
				var ea zjArenaExt
				zjDecode_Ext(l, &a.cRoot[len(a.cRoot)-1], &ea)
			}
			if l.Err() != nil {
				return
			}
			if !l.NextElem() {
				break
			}
		}
	}
	if len(a.cRoot) == 0 {
		a.cRoot = Exts{}
	}
	*v = a.cRoot
}

// ExtsDecoder decodes Exts values with fresh storage on every call.
// Later calls do not invalidate earlier results. Borrowed strings still alias the input.
type ExtsDecoder struct {
	busy atomic.Bool // reject overlapping calls on the same Decoder
}

// Decode decodes data into v using fresh per-call storage.
// *v is reset first; its pre-existing storage is not adopted.
// Storage supplied by callbacks may be used within this call.
// Later calls do not invalidate the result. Concurrent calls on one
// Decoder panic; use one Decoder per goroutine.
func (d *ExtsDecoder) Decode(data []byte, v *Exts) error {
	if !d.busy.CompareAndSwap(false, true) {
		panic("zerojson: concurrent Decode on the same ExtsDecoder — a Decoder is single-goroutine; use one per goroutine (for example via sync.Pool)")
	}
	// Deferred so a panic inside the decode (a user UnmarshalJSON, a
	// nil v) cannot leave the Decoder permanently "busy".
	defer d.busy.Store(false)
	var zero Exts
	*v = zero
	if err := zerojson.Valid(data); err != nil {
		return err
	}
	var a zjArenaExts
	l := zerojson.NewLexer(data, false)
	zjDecode_Exts(&l, v, &a)
	l.Finish()
	return l.Err()
}

// DecodeBorrow is Decode with zero-copy strings: decoded strings
// alias data, which must stay live and unmodified while v is used.
func (d *ExtsDecoder) DecodeBorrow(data []byte, v *Exts) error {
	if !d.busy.CompareAndSwap(false, true) {
		panic("zerojson: concurrent DecodeBorrow on the same ExtsDecoder — a Decoder is single-goroutine; use one per goroutine (for example via sync.Pool)")
	}
	// Deferred so a panic inside the decode (a user UnmarshalJSON, a
	// nil v) cannot leave the Decoder permanently "busy".
	defer d.busy.Store(false)
	var zero Exts
	*v = zero
	if err := zerojson.Valid(data); err != nil {
		return err
	}
	var a zjArenaExts
	l := zerojson.NewLexer(data, true)
	zjDecode_Exts(&l, v, &a)
	l.Finish()
	return l.Err()
}

// zjArenaExtIndex holds working storage for one ExtIndex decode.
type zjArenaExtIndex struct {
	mRoot ExtIndex
}

// AppendZJSON appends the JSON encoding of v to dst: a nil ExtIndex as null,
// a non-nil empty one as {}. On error the returned buffer holds a
// partial encoding and must be discarded.
func (v *ExtIndex) AppendZJSON(dst []byte) ([]byte, error) {
	if *v == nil {
		return append(dst, "null"...), nil
	}
	dst = append(dst, '{')
	first := true
	for mk, mv := range *v {
		if !first {
			dst = append(dst, ',')
		}
		first = false
		dst = zerojson.AppendString(dst, string(mk))
		dst = append(dst, ':')
		var err error
		dst, err = mv.AppendZJSON(dst)
		if err != nil {
			return dst, err
		}
	}
	return append(dst, '}'), nil
}

// UnmarshalZJSON decodes data into v. JSON null sets v to nil; {} decodes
// to a non-nil container; reused maps retain keys absent from the input.
func (v *ExtIndex) UnmarshalZJSON(data []byte) error {
	return v.unmarshalZJSON(data, false)
}

// UnmarshalZJSONBorrow is UnmarshalZJSON with zero-copy string decoding:
// decoded strings and Raw values may alias data, which must stay
// live and unmodified for the result's lifetime.
func (v *ExtIndex) UnmarshalZJSONBorrow(data []byte) error {
	return v.unmarshalZJSON(data, true)
}

func (v *ExtIndex) unmarshalZJSON(data []byte, borrow bool) error {
	if err := zerojson.Valid(data); err != nil {
		return err
	}
	l := zerojson.NewLexer(data, borrow)
	a := &zjArenaExtIndex{}
	zjDecode_ExtIndex(&l, v, a)
	l.Finish()
	return l.Err()
}

// ReadZJSON implements zerojson.Reader: it decodes the next JSON value
// from l into v, so ExtIndex can be a field of a zerojson-generated type in
// another package. Errors are reported through l, per the Reader contract.
func (v *ExtIndex) ReadZJSON(l *zerojson.Lexer) {
	a := &zjArenaExtIndex{}
	zjDecode_ExtIndex(l, v, a)
}

// zjDecode_ExtIndex decodes a JSON array/object root directly into v. Element (slice)
// and value (map) codecs are the same ones a slice/map field uses, so
// element structs keep their ordered fast path; the root loop itself is
// the plain array/object protocol.
func zjDecode_ExtIndex(l *zerojson.Lexer, v *ExtIndex, a *zjArenaExtIndex) {
	if l.IsNull() {
		*v = nil
		return
	}
	if *v != nil {
		a.mRoot = *v
	} else {
		a.mRoot = make(ExtIndex)
	}
	if l.EnterObject() {
		for {
			mk := string(string(l.ReadKey()))
			var mv Ext
			if !l.IsNull() {
				var ea zjArenaExt
				zjDecode_Ext(l, &mv, &ea)
			}
			if l.Err() != nil {
				return
			}
			a.mRoot[mk] = mv
			if !l.NextMember() {
				break
			}
		}
	}
	*v = a.mRoot
}

