// zjArenaSub holds per-call working state for a decoded Sub: publication
// flags, container headers, and nested types' arenas. It stays off the
// heap; pointer cells live in a cell block allocated on first use.
// Detached storage is not reused within the same decode.
type zjArenaSub struct {
	c1 []int
}

// AppendZJSON appends the JSON encoding of v to dst. On error the
// returned buffer contains a partial encoding and must be discarded.
func (v *Sub) AppendZJSON(dst []byte) ([]byte, error) {
	dst = append(dst, '{')
	n := len(dst)
	_ = n
	{
		if len(dst) > n {
			dst = append(dst, ',')
		}
		dst = append(dst, `"a":`...)
		dst = zerojson.AppendString(dst, string(v.A))
	}
	if len(v.B) != 0 {
		if len(dst) > n {
			dst = append(dst, ',')
		}
		dst = append(dst, `"b":`...)
		if v.B == nil {
			dst = append(dst, "null"...)
		} else {
			dst = append(dst, '[')
			for i := range v.B {
				if i > 0 {
					dst = append(dst, ',')
				}
				dst = zerojson.AppendInt64(dst, int64(v.B[i]))
			}
			dst = append(dst, ']')
		}
	}
	return append(dst, '}'), nil
}

// UnmarshalZJSON decodes data into v, copying strings and Raw values.
// Existing pointers and ordinary slice elements are reused as in stdlib.
// Registered leaf contracts may override traversal and reuse.
// Custom codecs define their own value/null behavior. Errors may leave v
// partially changed. Complete JSON grammar is validated before decoding.
func (v *Sub) UnmarshalZJSON(data []byte) error {
	return v.unmarshalZJSON(data, false)
}

// UnmarshalZJSONBorrow is UnmarshalZJSON with borrowed strings and Raw
// values. Keep data unmodified while any result refers to it; input
// buffers may be reused only after those results are no longer needed.
func (v *Sub) UnmarshalZJSONBorrow(data []byte) error {
	return v.unmarshalZJSON(data, true)
}

func (v *Sub) unmarshalZJSON(data []byte, borrow bool) error {
	if err := zerojson.Valid(data); err != nil {
		return err
	}
	l := zerojson.NewLexer(data, borrow)
	a := &zjArenaSub{}
	zjDecode_Sub(&l, v, a)
	l.Finish()
	return l.Err()
}

// ReadZJSON implements zerojson.Reader: it decodes the next JSON value
// from l into v, so Sub can be a field of a zerojson-generated type in
// another package. Errors are reported through l, per the Reader contract.
func (v *Sub) ReadZJSON(l *zerojson.Lexer) {
	a := &zjArenaSub{}
	zjDecode_Sub(l, v, a)
}
func zjFieldName_Sub(name string) string {
	switch name {
	case "a":
		return name
	case "b":
		return name
	}
	if strings_.EqualFold(name, "a") {
		return "a"
	}
	if strings_.EqualFold(name, "b") {
		return "b"
	}
	return name
}

// zjDecode_Sub tries the speculative ordered fast path first (see ordered.go),
// falling back to the general keyed decoder on any deviation from the
// compact, declaration-ordered shape zerojson's own encoder emits.
func zjDecode_Sub(l *zerojson.Lexer, v *Sub, a *zjArenaSub) {
	if l.IsNull() {
		// Null leaves a value-typed struct unchanged. The public wrapper
		// still calls Finish to reject trailing data.
		return
	}
	start := l.Mark()
	if zjDecodeOrdered_Sub(l, v, a) {
		return
	}
	if l.Err() != nil {
		// A value reader or strict skip already produced the final
		// decode error. Retrying cannot succeed and can duplicate
		// attacker-controlled allocation work (for example, a large
		// invalid base64 byte slice), so preserve the first error.
		return
	}
	l.OrderedBail(start)
	zjDecodeFallback_Sub(l, v, a)
}

// zjDecodeOrdered_Sub speculatively decodes a compact, declaration-ordered object
// (the shape zerojson's own encoder emits) directly into v, without
// the general keyed loop. A deviation at a member boundary (an
// out-of-order, duplicate, or escaped key, or non-compact syntax
// around one) hands the rest of the object to zjDecodeMembers_Sub:
// every member before it was decoded exactly as the keyed decoder
// would, so only the remainder needs the general path. Any other
// deviation returns false, and the caller rewinds via
// Lexer.OrderedBail and retries the object through zjDecodeFallback_Sub;
// real value/grammar errors are preserved without a redundant retry.
func zjDecodeOrdered_Sub(l *zerojson.Lexer, v *Sub, a *zjArenaSub) bool {
	_ = a
	// Caller-owned references and dynamic receivers must not be replayed.
	if v.B != nil {
		return false
	}
	data, pos := l.DataAndPos()
	if pos >= len(data) || data[pos] != '{' {
		return false
	}
	pos++
	if pos < len(data) && data[pos] == '}' {
		// An empty object still counts as a nesting level.
		if !l.DepthOK() {
			return false
		}
		l.SetPos(pos + 1)
		return true
	}
	l.SetPos(pos)
	// This decoder consumes the braces itself, so it accounts for the
	// nesting level itself too (EnterObject does this for the fallback):
	// an inline Skip of an unknown member must measure depth from here.
	// A bail leaves the level unbalanced; the dispatcher's OrderedBail
	// restores it along with the position.
	if !l.Enter() {
		return false
	}
	expected := 0
	for {
		memberPos := l.Pos()
		matched := -1
		for k := expected; k < 2; k++ {
			if zjTryOrderedKeySub(l, k) {
				matched = k
				break
			}
		}
		if matched < 0 {
			// A whitespace-padded empty object (`{ }`) is valid but
			// cannot literal-match the compact fast path. Bail without
			// asking ReadKey to parse the closing brace as a string;
			// the fallback will consume it through EnterObject.
			if l.IsDelim('}') {
				return false
			}
			// No declared field k >= expected literal-matched at this
			// position. Read the key properly (ReadKey tolerates
			// whitespace and unescapes, unlike the word-compare above)
			// and check its *name*, not its byte position: a declared
			// name here — regardless of index — means duplicate,
			// out-of-order, non-compact syntax around an otherwise
			// valid key, or an escaped key that decodes to a declared
			// name. The keyed decoder's last-wins/general handling
			// takes over from this member. Only a name matching no
			// declared field (folded as the keyed decoder folds it) is
			// genuinely unknown and safe to skip inline (the
			// projection-struct fast path).
			key := l.ReadKey()
			if l.Err() != nil {
				return false
			}
			if zjIsDeclaredKeySub(string(key)) {
				l.SetPos(memberPos)
				zjDecodeMembers_Sub(l, v, a)
				return l.Err() == nil
			}
			l.Skip()
			if l.Err() != nil {
				return false
			}
		} else {
			if !zjDecodeOrderedField_Sub(l, v, a, matched) {
				return false
			}
			expected = matched + 1
		}
		d, p := l.DataAndPos()
		if p >= len(d) {
			return false
		}
		switch d[p] {
		case ',':
			l.SetPos(p + 1)
		case '}':
			l.SetPos(p + 1)
			l.Leave()
			return true
		default:
			// Whitespace before the separator: the member is complete,
			// so the keyed decoder continues from here. NextMember
			// leaves the nesting level on the closing brace.
			if l.NextMember() {
				zjDecodeMembers_Sub(l, v, a)
			}
			return l.Err() == nil
		}
	}
}

func zjDecodeOrderedField_Sub(l *zerojson.Lexer, v *Sub, a *zjArenaSub, k int) bool {
	if l.IsNull() {
		switch k {
		case 1:
			v.B = nil
		}
		if l.Err() != nil {
			l.AnnotateFieldString(zjFieldNamesSub[k])
			return false
		}
		return true
	}
	switch k {
	case 0:
		v.A = l.ReadString()
	case 1:
		if v.B != nil {
			if l.IsNull() {
				v.B = nil
			} else if l.EnterArray() {
				zjSlice := v.B
				zjIndex := 0
				for {
					if zjIndex < cap(zjSlice) {
						zjSlice = zjSlice[:zjIndex+1]
					} else {
						var zjZero int
						zjSlice = append(zjSlice, zjZero)
					}
					if !l.IsNull() {
						zjSlice[zjIndex] = int(l.ReadInt())
					}
					zjIndex++
					if l.Err() != nil || !l.NextElem() {
						break
					}
				}
				v.B = zjSlice[:zjIndex]
			} else if l.Err() == nil {
				v.B = make([]int, 0)
			}
		} else {
			if v.B != nil {
				a.c1 = v.B
			} else {
				a.c1 = nil
			}
			a.c1 = a.c1[:0]
			if l.EnterArray() {
				for {
					if len(a.c1) == cap(a.c1) {
						var zjZero int
						a.c1 = append(a.c1, zjZero)
					} else {
						a.c1 = a.c1[:len(a.c1)+1]
						var zjZero int
						a.c1[len(a.c1)-1] = zjZero
					}
					idx := len(a.c1) - 1
					if !l.IsNull() {
						a.c1[idx] = int(l.ReadInt())
					}
					if l.Err() != nil {
						break
					}
					if !l.NextElem() {
						break
					}
				}
			}
			if len(a.c1) == 0 {
				a.c1 = []int{}
			}
			v.B = a.c1
		}
	}
	if l.Err() != nil {
		l.AnnotateFieldString(zjFieldNamesSub[k])
		return false
	}
	return true
}

// zjFieldNamesSub are Sub's JSON field names by declared index, for error paths.
var zjFieldNamesSub = [...]string{
	"a",
	"b",
}

// zjTryOrderedKeySub matches and consumes the literal `"name":` for declared
// field index k at l's current position (compact JSON only — any
// whitespace simply fails the comparison). Leaves the position
// unchanged on mismatch.
func zjTryOrderedKeySub(l *zerojson.Lexer, k int) bool {
	data, pos := l.DataAndPos()
	n := len(data)
	switch k {
	case 0:
		if n-pos < 4 {
			return false
		}
		if binary.LittleEndian.Uint32(data[pos+0:]) != 0x3a226122 {
			return false
		}
		l.SetPos(pos + 4)
		return true
	case 1:
		if n-pos < 4 {
			return false
		}
		if binary.LittleEndian.Uint32(data[pos+0:]) != 0x3a226222 {
			return false
		}
		l.SetPos(pos + 4)
		return true
	}
	return false
}

func zjIsDeclaredKeySub(name string) bool {
	switch name {
	case "a", "b":
		return true
	}
	return zjFieldName_Sub(name) != name
}

// zjDecodeFallback_Sub is the general keyed decoder: every member is read via
// ReadKey and dispatched by a string switch. It handles arbitrary
// field order and is the fallback for structural ordered-path mismatches.
func zjDecodeFallback_Sub(l *zerojson.Lexer, v *Sub, a *zjArenaSub) {
	_ = a
	if !l.EnterObject() {
		return
	}
	zjDecodeMembers_Sub(l, v, a)
}

// zjDecodeMembers_Sub decodes the remaining members of an object whose opening
// brace and nesting level are already consumed, positioned at a key.
func zjDecodeMembers_Sub(l *zerojson.Lexer, v *Sub, a *zjArenaSub) {
	_ = a
	for {
		key := l.ReadKey()
		if l.Err() != nil {
			return
		}
		name := string(key)
		if l.IsNull() {
			name = zjFieldName_Sub(name)
			switch name {
			case "b":
				v.B = nil
			}
			if l.Err() != nil {
				l.AnnotateField(key)
				return
			}
			if !l.NextMember() {
				break
			}
			continue
		}
	zjDispatch:
		switch name {
		case "a":
			v.A = l.ReadString()
		case "b":
			if v.B != nil {
				if l.IsNull() {
					v.B = nil
				} else if l.EnterArray() {
					zjSlice := v.B
					zjIndex := 0
					for {
						if zjIndex < cap(zjSlice) {
							zjSlice = zjSlice[:zjIndex+1]
						} else {
							var zjZero int
							zjSlice = append(zjSlice, zjZero)
						}
						if !l.IsNull() {
							zjSlice[zjIndex] = int(l.ReadInt())
						}
						zjIndex++
						if l.Err() != nil || !l.NextElem() {
							break
						}
					}
					v.B = zjSlice[:zjIndex]
				} else if l.Err() == nil {
					v.B = make([]int, 0)
				}
			} else {
				if v.B != nil {
					a.c1 = v.B
				} else {
					a.c1 = nil
				}
				a.c1 = a.c1[:0]
				if l.EnterArray() {
					for {
						if len(a.c1) == cap(a.c1) {
							var zjZero int
							a.c1 = append(a.c1, zjZero)
						} else {
							a.c1 = a.c1[:len(a.c1)+1]
							var zjZero int
							a.c1[len(a.c1)-1] = zjZero
						}
						idx := len(a.c1) - 1
						if !l.IsNull() {
							a.c1[idx] = int(l.ReadInt())
						}
						if l.Err() != nil {
							break
						}
						if !l.NextElem() {
							break
						}
					}
				}
				if len(a.c1) == 0 {
					a.c1 = []int{}
				}
				v.B = a.c1
			}
		default:
			if folded := zjFieldName_Sub(name); folded != name {
				name = folded
				goto zjDispatch
			}
			l.Skip()
		}
		if l.Err() != nil {
			l.AnnotateField(key)
			return
		}
		if !l.NextMember() {
			break
		}
	}
}
